sys_ws_operation.operation_script:
(function process(request, response) {
  try {
    var assetTag = request.pathParams['asset_tag'];
    var body = request.body.data;

    // Reject updates to immutable asset_tag field
    if (body.asset_tag !== undefined) {
      response.setStatus(400);
      response.setBody({ error: 'The asset_tag field is immutable and cannot be updated' });
      return;
    }

    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addQuery('asset_tag', assetTag);
    gr.query();

    if (!gr.next()) {
      response.setStatus(404);
      response.setBody({ error: 'Asset not found' });
      return;
    }

    // Update only provided fields
    var allowedFields = [
      'display_name', 'asset_type', 'lifecycle_state', 'serial_number',
      'assigned_to', 'location', 'purchase_date', 'warranty_expiry',
      'last_audit_date', 'external_id'
    ];

    for (var i = 0; i < allowedFields.length; i++) {
      var field = allowedFields[i];
      if (body[field] !== undefined) {
        gr.setValue(field, body[field]);
      }
    }

    gr.update();

    response.setStatus(200);
    response.setBody({
      status: 'updated',
      sys_id: gr.getUniqueValue(),
      asset_tag: gr.getValue('asset_tag')
    });
  } catch (e) {
    gs.error('TechDesk CMDB Update Asset error: ' + e.message);
    response.setStatus(500);
    response.setBody({ error: 'Internal server error', message: e.message });
  }
})(request, response);
